@font-face {
  font-family: "Bricolage Grotesque";
  src: url("fonts/bricolage-grotesque-latin.woff2") format("woff2");
  font-weight: 400 800;
  font-style: normal;
  font-display: swap;
}

:root {
  color-scheme: light;
  --background: #f7f1e7;
  --surface: #fffaf2;
  --ink: #241b14;
  --muted: #514235;
  --line: #d8c8b6;
  --accent: #a83e1b;
  --tint: #f4d7b7;
  font-family: "Bricolage Grotesque", system-ui, sans-serif;
  font-optical-sizing: auto;
}

@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;
    --background: #17120e;
    --surface: #241c16;
    --ink: #fff3e4;
    --muted: #e5d2bc;
    --line: #4a382a;
    --accent: #ffab7a;
    --tint: #40281a;
  }
}

* { box-sizing: border-box; }
body { margin: 0; background: var(--background); color: var(--ink); line-height: 1.7; }
a { color: var(--accent); text-underline-offset: 0.2em; overflow-wrap: anywhere; }
a:hover { text-decoration-thickness: 2px; }
a:focus-visible { outline: 3px solid var(--accent); outline-offset: 5px; border-radius: 2px; }
.shell { width: min(1040px, calc(100% - 40px)); margin-inline: auto; }
.skip { position: absolute; top: -100px; padding: 12px; background: var(--surface); z-index: 1; }
.skip:focus { top: 12px; left: 20px; }
.header { display: flex; justify-content: space-between; align-items: center; gap: 24px; padding-block: 28px; border-bottom: 1px solid var(--line); }
.brand { display: grid; color: var(--ink); text-decoration: none; line-height: 1; }
.brand strong { font-size: 25px; font-weight: 800; letter-spacing: -0.04em; }
.brand span { display: flex; justify-content: space-between; margin-top: 7px; font-size: 11px; font-weight: 600; }
.brand span b { font-weight: inherit; }
nav { display: flex; flex-wrap: wrap; gap: 8px 24px; }
nav a { color: var(--muted); font-size: 15px; }
nav a[aria-current="page"] { color: var(--accent); text-decoration-thickness: 2px; }
.intro { max-width: 760px; padding-block: 64px 36px; }
.eyebrow { color: var(--accent); font-size: 12px; font-weight: 700; letter-spacing: 0.16em; text-transform: uppercase; }
h1 { font-size: clamp(2.5rem, 7vw, 4.5rem); line-height: 1.08; letter-spacing: -0.05em; margin: 18px 0; }
.lead { font-size: 20px; color: var(--muted); max-width: 660px; }
.date { color: var(--muted); font-size: 14px; }
.summary { padding: 20px 24px; background: var(--tint); border: 1px solid var(--line); border-radius: 12px; }
.summary p { margin: 0; }
.layout { display: grid; grid-template-columns: 220px minmax(0, 1fr); gap: 56px; padding-block: 40px 64px; align-items: start; }
.contents { position: sticky; top: 24px; font-size: 14px; }
.contents strong { display: block; margin-bottom: 12px; }
.contents ol { margin: 0; padding-left: 20px; }
.contents li { padding-block: 5px; }
article { min-width: 0; }
article section + section { border-top: 1px solid var(--line); margin-top: 28px; padding-top: 28px; }
h2 { font-size: 24px; line-height: 1.3; letter-spacing: -0.025em; margin: 0 0 16px; }
p { margin: 0 0 16px; }
p:last-child { margin-bottom: 0; }
li + li { margin-top: 8px; }
ul { padding-left: 24px; }
code { font-family: ui-monospace, monospace; font-size: 0.88em; overflow-wrap: anywhere; }
.cards { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 20px; padding-bottom: 64px; }
.card { padding: 28px; border: 1px solid var(--line); border-radius: 12px; background: var(--surface); }
.card p { color: var(--muted); }
.footer { padding-block: 28px 40px; border-top: 1px solid var(--line); color: var(--muted); font-size: 14px; }
.footer p + p { margin-top: 8px; }
@media (max-width: 720px) {
  .layout { grid-template-columns: 1fr; gap: 32px; }
  .contents { position: static; padding-bottom: 24px; border-bottom: 1px solid var(--line); }
  .intro { padding-top: 40px; }
  .header { flex-wrap: wrap; gap: 20px; }
  .cards { grid-template-columns: 1fr; }
}
@media print {
  :root { color-scheme: light; --background: #fff; --surface: #fff; --ink: #000; --muted: #222; --accent: #000; --line: #bbb; --tint: #fff; }
  .layout { display: block; }
  .contents, .skip, nav { display: none; }
  .intro { padding-top: 24px; }
  section { break-inside: avoid; }
}
